  "bounded contexts": {
    "Maintenance": {
      "derived from": "Maintenance Subdomain",
      "objects": [
        "Irregularity Report",
        "Maintenance Engineer",
        "Inspection",
        "Asset",
        "Maintenance Record",
        "Maintenance Extension Notification"
      ],
      "name changes": [
        "Aircraft -> Asset"
      ]
    },
    "Passenger Affairs": {
      "derived from": "Passenger Affairs Subdomain",
      "objects": [
        "Customer Service Agent",
